  vec3 lit = base * (0.12 + 0.88 * diffuse * sh);
  float spec = pow(max(dot(reflect(-l, n), -rd), 0.0), 48.0) * sh;
  vec3 shaded = mix(lit, vec3(1.0), spec * 0.5);
  float fog = 1.0 - exp(-t * t * 0.07);
