    k.xyy * map(p + k.xyy * 0.001) +
    k.yyx * map(p + k.yyx * 0.001) +
    k.yxy * map(p + k.yxy * 0.001) +
    k.xxx * map(p + k.xxx * 0.001)
  );
}

float softShadow(vec3 ro, vec3 rd, float k) {
  float res = 1.0;
  float t = 0.05;
  for (int i = 0; i < 48; i++) {
    float d = map(ro + rd * t);
    res = min(res, k * d / t);
    if (d < 0.001) return 0.0;
    t += d;
    if (t > 12.0) break;
  }
  return clamp(res, 0.0, 1.0);
}
